import json
code = r'''
import numpy as np
RES = np.array([83,88,222,254,444,495,506,601])
KEEP = np.setdiff1d(np.arange(768), RES)
def lnr(X):
    X = X[:, KEEP] if X.shape[1]==768 else X
    X = X - X.mean(1, keepdims=True)
    return X / np.sqrt((X**2).mean(1, keepdims=True) + 1e-12)
def zs(Xtr, Xte=None):
    mu = Xtr.mean(0); sd = Xtr.std(0)+1e-6
    return ((Xtr-mu)/sd, None if Xte is None else (Xte-mu)/sd)
def rbf(A, B, gamma):
    d = A.shape[1]
    A2=(A**2).sum(1)[:,None]; B2=(B**2).sum(1)[None]
    D = np.maximum(A2+B2-2*A@B.T, 0)/d
    return np.exp(-gamma*D)
def krr_loo(X, y, gamma=0.4, lam=0.003, C=8):
    Z,_ = zs(X)
    K = rbf(Z, Z, gamma)
    T = np.eye(C)[y]; T = T - T.mean(0)
    Ainv = np.linalg.inv(K + lam*np.eye(len(y)))
    al = Ainv@T
    P = T - al/np.diag(Ainv)[:,None]
    return (P.argmax(1)==y).mean()
'''
open('krr.py','w').write(code)
